from jsonb_to_recordset($json$[{"id":"che-so-209","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Boiling point rises because the solution must be heated until its","options":["vapour pressure again equals the external pressure","freezing point equals 0 °C","osmotic pressure vanishes","$K_H$ is zero"],"answer_index":0,"explanation":"A non-volatile solute lowers p, so a higher T is needed to restore p = 1 atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-210","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A convenient unit of $K_b$ is","options":["K kg mol⁻¹","K L mol⁻¹","atm kg mol⁻¹","J mol⁻¹"],"answer_index":0,"explanation":"$\\Delta T_b = K_b m$ with m in mol kg⁻¹, so $K_b$ has unit K kg mol⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-211","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For water, the usual textbook $K_b$ is about","options":["0.52 K kg mol⁻¹","1.86 K kg mol⁻¹","0.0821 L atm K⁻¹ mol⁻¹","13.6 eV"],"answer_index":0,"explanation":"The ebullioscopic constant of water is 0.512 K kg mol⁻¹ (often rounded to 0.52).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-212","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Molar mass of a non-volatile solute follows from $\\Delta T_b$ if one also knows","options":["$K_b$ and the masses (or molality)","only the colour of the solution","only $K_H$","only the density of air"],"answer_index":0,"explanation":"$m = \\Delta T_b / K_b$ and $m = (w_B / M_B) / w_A$ together give $M_B$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-213","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Elevation of boiling point is classified as a","options":["colligative property","chemical property of the solute","nuclear property","surface property only"],"answer_index":0,"explanation":"It depends on the number of solute particles, not on their identity (for a non-electrolyte).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-214","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Between two dilute aqueous non-electrolytes, the larger boiling-point elevation belongs to the solution of","options":["higher molality","lower molality","smaller $K_b$","zero mole fraction"],"answer_index":0,"explanation":"$\\Delta T_b = K_b m$ with the same $K_b$ (water), so the more molal solution boils higher.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-215","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 1 molal aqueous non-electrolyte, taking $K_b = 0.52$ K kg mol⁻¹, is expected to boil near","options":["100.52 °C","98.14 °C","100.00 °C","0.52 °C"],"answer_index":0,"explanation":"$\\Delta T_b = 0.52$ K, so the boiling point is about 100.52 °C at 1 atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-216","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Glucose at 0.50 mol kg⁻¹ in water ($K_b = 0.512$ K kg mol⁻¹) elevates the boiling point by","options":["0.256 K","0.512 K","1.02 K","0.128 K"],"answer_index":0,"explanation":"$\\Delta T_b = 0.512 \\times 0.50 = 0.256$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-217","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A solution boils 0.208 °C above the pure solvent. If $K_b = 0.52$ K kg mol⁻¹, the molality is","options":["0.40 m","0.208 m","2.5 m","0.52 m"],"answer_index":0,"explanation":"$m = \\Delta T_b / K_b = 0.208 / 0.52 = 0.40$ mol kg⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-218","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Urea 3.0 g (60 g mol⁻¹) in 250 g water ($K_b = 0.52$ K kg mol⁻¹) gives $\\Delta T_b$ of","options":["0.104 K","0.52 K","0.208 K","1.04 K"],"answer_index":0,"explanation":"m = (3.0/60) / 0.250 = 0.20 mol kg⁻¹; $\\Delta T_b = 0.52 \\times 0.20 = 0.104$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-219","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Solvent X has $K_b$ twice that of water. The same molal non-electrolyte in X, compared with water, shows $\\Delta T_b$ that is","options":["twice as large","half as large","equal","zero"],"answer_index":0,"explanation":"$\\Delta T_b$ scales directly with $K_b$ at fixed molality.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-220","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A non-volatile solute of molar mass 180 g mol⁻¹, 9.0 g, in 200 g of a solvent ($K_b = 2.5$ K kg mol⁻¹) raises the boiling point by","options":["0.625 K","2.5 K","0.25 K","1.25 K"],"answer_index":0,"explanation":"n = 0.050 mol in 0.200 kg, so m = 0.25 mol kg⁻¹ and $\\Delta T_b = 2.5 \\times 0.25 = 0.625$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
